def _detect_line_ending(source: IO[str]) -> str:
    \"\"\"Detect the first LF or CRLF line-ending style in the stream.

    Returns \"\\r\\n\" if the first line ending is CRLF, \"\\n\" if it is LF, or
    \"\\n\" when the stream contains no line ending at all.
    \"\"\"
    content = source.read()
    source.seek(0)
    for i, ch in enumerate(content):
        if ch == \"\\n\":
            return \"\\r\\n\" if i > 0 and content[i - 1] == \"\\r\" else \"\\n\"
        if ch == \"\\r\":
            return \"\\r\\n\" if i + 1 < len(content) and content[i + 1] == \"\\n\" else \"\\n\"
    return \"\\n\"


